const questions=[{key:'role',title:'What is your main role?',options:['Recording artist','Producer','Songwriter','DJ','Instrumentalist','Artist and producer','Other']},{key:'stage',title:'What stage are you at?',options:['Just starting','Released music, building an audience','Growing my career','Established independent artist']},{key:'goal',title:'What is your main goal?',options:['Release my first music','Grow my audience','Earn more from music','Improve career management','Find collaborators and opportunities']}];
let step=0,answers={};const demo=new URLSearchParams(location.search).get('demo')==='1';try{answers=JSON.parse(sessionStorage.getItem('uniify-onboarding-draft')||'{}')}catch{}
const form=document.querySelector('#flow-form'),message=document.querySelector('#flow-status');
function show(){const q=questions[step];document.querySelector('#auth-title').textContent=q.title;document.querySelector('#step-label').textContent=`${demo?'Demo setup · ':''}Step ${step+1} of 3`;document.querySelector('.onboarding-progress').innerHTML=questions.map((_,i)=>`<span class="${i<=step?'complete':''}"></span>`).join('');document.querySelector('#onboarding-question').innerHTML='<fieldset class="onboarding-options"><legend class="visually-hidden">'+q.title+'</legend>'+q.options.map((v,i)=>`<label><input type="radio" name="answer" value="${i}" required ${answers[q.key]===v?'checked':''}><span>${v}</span></label>`).join('')+'</fieldset>';document.querySelector('#step-back').hidden=step===0;document.querySelector('#step-next').textContent=step===2?'Open workspace':'Continue';}
function remember(){const selected=form.querySelector(':checked');if(selected)answers[questions[step].key]=questions[step].options[Number(selected.value)];sessionStorage.setItem('uniify-onboarding-draft',JSON.stringify(answers))}
form.onchange=remember;document.querySelector('#step-back').onclick=()=>{remember();step--;show()};form.onsubmit=async e=>{e.preventDefault();remember();if(step<2){step++;show();form.querySelector('input').focus();return}const button=document.querySelector('#step-next');button.disabled=true;try{if(!demo){const response=await fetch('/api/auth/onboarding',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(answers)});if(!response.ok||!response.headers.get('content-type')?.includes('application/json'))throw Error('Sign up and verify your email first, or use the demo setup.');}const key='uniify-workspace-v2',saved=JSON.parse(localStorage.getItem(key)||'null')||{version:3,tasks:[],releases:[],entries:[],history:[],activity:[],answers:{}};saved.profile={...saved.profile,...answers};const name=sessionStorage.getItem('uniify-pending-name');if(name&&!demo)saved.profile.artist=name;saved.onboarding={completedAt:new Date().toISOString(),demo};localStorage.setItem(key,JSON.stringify(saved));sessionStorage.removeItem('uniify-onboarding-draft');sessionStorage.removeItem('uniify-pending-name');location.href='workspace.html#releases'}catch(error){message.textContent=error.message;button.disabled=false}};show();
